/* ============================================================
   50 HUMANS — a very bad horror game
   all styling is intentionally a little bit cursed
   ============================================================ */

:root {
  --ink: #100c0b;
  --paper: #efe2bf;
  --paper-dark: #d8c89e;
  --cream: #fff3cf;
  --red: #d52a2a;
  --red-dark: #7e1010;
  --green: #4dbb62;
  --green-dark: #1f6e33;
  --purple: #6b3ba8;
  --blood: #9d0a0a;
  --ui: "Trebuchet MS", "Arial Black", "Segoe UI", sans-serif;
  --hand: "Comic Sans MS", "Chalkboard SE", "Bradley Hand", cursive;
  --mono: "Courier New", ui-monospace, monospace;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #050303;
  color: var(--cream);
  font-family: var(--ui);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { touch-action: none; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #050303;
}

.hidden { display: none !important; }

/* ------------------------------------------------------------
   THE GAME CANVAS
   ------------------------------------------------------------ */
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  cursor: crosshair;
  background: #050303;
}
body.dragging #game { cursor: grabbing; }

/* ------------------------------------------------------------
   VHS / GRAIN / VIGNETTE
   ------------------------------------------------------------ */
#vhs {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  background:
    repeating-linear-gradient(
      to bottom,
      rgba(0, 0, 0, 0) 0px,
      rgba(0, 0, 0, 0) 2px,
      rgba(0, 0, 0, 0.13) 3px,
      rgba(0, 0, 0, 0.13) 4px
    ),
    radial-gradient(ellipse at center, rgba(0,0,0,0) 42%, rgba(0,0,0,0.38) 77%, rgba(0,0,0,0.82) 100%);
  opacity: 0.72;
  mix-blend-mode: multiply;
}
#vhs::before {
  content: "";
  position: absolute;
  inset: -20%;
  background-image:
    radial-gradient(rgba(255,255,255,0.14) 0.6px, transparent 0.8px),
    radial-gradient(rgba(255,255,255,0.09) 0.6px, transparent 0.8px);
  background-size: 3px 3px, 5px 5px;
  background-position: 1px 1px, 3px 2px;
  opacity: 0.18;
  animation: grainShift 0.22s steps(2) infinite;
}
#vhs::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: 15%;
  top: -20%;
  background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.055), transparent);
  animation: tracking 9s linear infinite;
}
@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-1px, 1px); }
  50% { transform: translate(1px, 0); }
  75% { transform: translate(0, -1px); }
  100% { transform: translate(1px, 1px); }
}
@keyframes tracking {
  0% { top: -20%; opacity: 0; }
  8% { opacity: 1; }
  22% { top: 110%; opacity: 0.8; }
  23%, 100% { top: 110%; opacity: 0; }
}

#flash {
  position: absolute;
  inset: 0;
  z-index: 56;
  pointer-events: none;
  background: #fff;
  opacity: 0;
}
#flash.on { animation: whiteFlash 0.52s steps(3) 1; }
#flash.red { background: #a80000; }
#flash.on-red { animation: redFlash 0.42s steps(2) 1; }
@keyframes whiteFlash {
  0% { opacity: 0; }
  8% { opacity: 0.88; }
  20% { opacity: 0.05; }
  34% { opacity: 0.62; }
  52% { opacity: 0; }
  100% { opacity: 0; }
}
@keyframes redFlash {
  0% { opacity: 0; }
  12% { opacity: 0.65; }
  36% { opacity: 0.1; }
  56% { opacity: 0.4; }
  100% { opacity: 0; }
}

/* ------------------------------------------------------------
   HUD
   ------------------------------------------------------------ */
#hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  padding: calc(var(--safe-top) + 16px) max(16px, env(safe-area-inset-right)) calc(var(--safe-bottom) + 14px) max(16px, env(safe-area-inset-left));
}
#hud.hud-off { opacity: 0; }

#topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}

#objective-wrap {
  background: rgba(9, 6, 5, 0.74);
  border: 2px solid rgba(255, 243, 207, 0.22);
  border-left: 4px solid var(--red);
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.42);
  padding: 10px 14px 11px;
  max-width: min(500px, 63vw);
  backdrop-filter: blur(2px);
}

.small-label {
  display: block;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.22em;
  color: #c09e75;
  margin-bottom: 3px;
}

#objective {
  font-family: var(--ui);
  font-weight: 800;
  font-size: clamp(13px, 1.5vw, 18px);
  line-height: 1.25;
  letter-spacing: 0.015em;
  text-transform: uppercase;
  color: #fff3cf;
  text-shadow: 1px 1px 0 #000;
}

#counter {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 8px;
  font-family: var(--mono);
  font-weight: 700;
  font-size: clamp(10px, 1.1vw, 13px);
  letter-spacing: 0.09em;
  color: #f5c88e;
}
#counter b {
  font-size: 1.65em;
  color: #fff;
  line-height: 1;
  margin: 0 1px;
  text-shadow: 0 0 10px rgba(255, 110, 40, 0.65);
}
#counter .slash { color: #7e6a58; }
#counter .face-ico { font-size: 1.3em; color: #ffd18d; }
#counter.pop { animation: counterPop 0.4s ease-out; }
@keyframes counterPop {
  0% { transform: scale(1); }
  40% { transform: scale(1.18); color: #baff7c; }
  100% { transform: scale(1); }
}

#topright {
  display: flex;
  gap: 8px;
  pointer-events: auto;
}
.chip {
  appearance: none;
  border: 2px solid rgba(255, 243, 207, 0.25);
  background: rgba(9, 6, 5, 0.72);
  color: #d9c6a2;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 7px 9px;
  cursor: pointer;
  box-shadow: 2px 2px 0 rgba(0,0,0,0.5);
}
.chip:hover { background: #261713; color: #fff; }

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 18px;
  height: 18px;
  transform: translate(-50%, -50%);
  opacity: 0.55;
  transition: opacity 0.2s;
}
#crosshair.hot { opacity: 1; }
#crosshair i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 4px;
  height: 4px;
  margin: -2px 0 0 -2px;
  background: #fff3cf;
  border-radius: 50%;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.8), 0 0 8px rgba(255,240,190,0.65);
}
#crosshair.hot i { background: #ffd15e; transform: scale(1.5); }

/* captions */
#caption {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 128px);
  transform: translateX(-50%);
  width: min(760px, 90vw);
  text-align: center;
  font-family: var(--mono);
  font-size: clamp(12px, 1.35vw, 16px);
  font-weight: 700;
  letter-spacing: 0.035em;
  line-height: 1.45;
  color: #ffefc7;
  background: rgba(4, 3, 3, 0.74);
  border-left: 3px solid var(--red);
  border-right: 3px solid var(--red);
  padding: 9px 15px;
  text-shadow: 1px 1px 0 #000;
  pointer-events: none;
  animation: captionIn 0.2s ease-out;
}
@keyframes captionIn {
  from { opacity: 0; transform: translate(-50%, 5px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

/* buttons / prompts */
#prompt {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 50px);
  transform: translateX(-50%);
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  width: min(880px, 94vw);
  pointer-events: auto;
}
.prompt-btn {
  appearance: none;
  border: 2px solid #fff3cf;
  background: #1b1210;
  color: #fff3cf;
  font-family: var(--ui);
  font-weight: 900;
  font-size: clamp(12px, 1.2vw, 15px);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 10px 16px;
  cursor: pointer;
  box-shadow: 3px 3px 0 #000;
  display: flex;
  align-items: center;
  gap: 9px;
  transition: transform 0.07s, background 0.1s;
}
.prompt-btn:hover { background: #34201b; transform: translate(-1px, -1px); box-shadow: 4px 4px 0 #000; }
.prompt-btn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #000; }
.prompt-btn.green { border-color: #a9f7ab; color: #d9ffd8; background: #16301a; }
.prompt-btn.green:hover { background: #23512a; }
.prompt-btn.red { border-color: #ff9e9e; color: #ffe3e3; background: #351010; }
.prompt-btn.red:hover { background: #5b1616; }
.prompt-btn.ghost { border-color: rgba(255,243,207,0.28); color: #c8b28c; background: rgba(10,7,6,0.78); }
.prompt-btn.ghost:hover { background: #201512; }
.prompt-btn:disabled { opacity: 0.4; cursor: not-allowed; }

.key {
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  line-height: 1;
  padding: 3px 5px 4px;
  color: #1b1210;
  background: #fff3cf;
  border-radius: 2px;
  letter-spacing: 0;
}

#hintbar {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 11px);
  transform: translateX(-50%);
  color: rgba(255, 243, 207, 0.4);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.09em;
  white-space: nowrap;
  text-transform: uppercase;
}
.touch-hint { display: none; }
body.touch .desk-hint { display: none; }
body.touch .touch-hint { display: inline; }

/* toast */
#toast {
  position: absolute;
  left: 50%;
  top: 34%;
  transform: translate(-50%, -50%) rotate(-2deg);
  font-family: var(--ui);
  font-weight: 900;
  text-transform: uppercase;
  text-align: center;
  font-size: clamp(22px, 3.7vw, 46px);
  line-height: 1.05;
  color: #fff5cf;
  text-shadow: 3px 3px 0 #000, 0 0 25px rgba(255, 90, 30, 0.6);
  padding: 12px 22px;
  border: 3px solid rgba(255, 243, 207, 0.6);
  background: rgba(10, 5, 4, 0.72);
  pointer-events: none;
  animation: toastPop 0.24s cubic-bezier(.2,1.6,.5,1);
  max-width: 90vw;
}
@keyframes toastPop {
  from { opacity: 0; transform: translate(-50%, -50%) rotate(-2deg) scale(0.65); }
  to { opacity: 1; transform: translate(-50%, -50%) rotate(-2deg) scale(1); }
}

/* ------------------------------------------------------------
   SCREENS / MODALS
   ------------------------------------------------------------ */
.screen {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: calc(var(--safe-top) + 18px) 18px calc(var(--safe-bottom) + 18px);
}
.modal {
  position: absolute;
  inset: 0;
  z-index: 45;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(3, 2, 2, 0.82);
  backdrop-filter: blur(4px);
  padding: calc(var(--safe-top) + 14px) 14px calc(var(--safe-bottom) + 14px);
}

/* ---------------- title ---------------- */
#title {
  background:
    radial-gradient(ellipse at 50% 42%, rgba(100, 34, 24, 0.24), transparent 60%),
    linear-gradient(180deg, #080505 0%, #120a08 48%, #050303 100%);
  z-index: 50;
  overflow: hidden;
}
#title::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent 0 49.7%, rgba(210, 28, 28, 0.08) 49.8% 50.2%, transparent 50.3%),
    radial-gradient(circle at 50% 50%, transparent 0 40%, rgba(0,0,0,0.55) 100%);
  pointer-events: none;
}
.title-static {
  position: absolute;
  inset: -10%;
  opacity: 0.11;
  background-image:
    repeating-linear-gradient(0deg, rgba(255,255,255,0.3) 0 1px, transparent 1px 3px),
    radial-gradient(rgba(255,255,255,0.6) 0.5px, transparent 0.7px);
  background-size: auto, 4px 4px;
  animation: titleStatic 0.26s steps(3) infinite;
  pointer-events: none;
}
@keyframes titleStatic {
  0% { transform: translate(0,0); }
  50% { transform: translate(2px,-1px); }
  100% { transform: translate(-1px,2px); }
}
.title-inner {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  max-width: 780px;
}
.vhs-tag {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.22em;
  color: #c8b28c;
  margin-bottom: 30px;
  opacity: 0.85;
}
.vhs-tag i {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #e03030;
  margin-right: 6px;
  animation: recBlink 1.1s steps(1) infinite;
}
@keyframes recBlink { 50% { opacity: 0.15; } }

.eyebrow {
  margin: 0 0 8px;
  font-family: var(--mono);
  font-size: clamp(8px, 1vw, 11px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #9d8265;
}
#title h1 {
  margin: 0;
  font-family: var(--ui);
  font-weight: 900;
  font-size: clamp(68px, 15vw, 178px);
  line-height: 0.78;
  letter-spacing: -0.075em;
  color: #f1dfb7;
  text-shadow:
    4px 4px 0 #6d0808,
    -3px -3px 0 #0a5b5b,
    0 0 38px rgba(201, 35, 28, 0.32);
  animation: titleJitter 4.2s steps(1) infinite;
}
#title h1 span {
  display: block;
  font-size: 0.47em;
  letter-spacing: 0.24em;
  color: #c81f1f;
  text-shadow: 2px 2px 0 #220303, -2px -2px 0 #053b3b;
  margin-top: 8px;
}
@keyframes titleJitter {
  0%, 91%, 94%, 100% { transform: translate(0,0) skewX(0); }
  92% { transform: translate(-4px,1px) skewX(-2deg); }
  93% { transform: translate(3px,-2px) skewX(1.4deg); }
}
.tagline {
  margin: 24px 0 0;
  font-family: var(--mono);
  font-size: clamp(11px, 1.3vw, 14px);
  line-height: 1.6;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #c7ae86;
}
.warn {
  margin: 20px 0 24px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  color: #de6b63;
  border: 1px dashed rgba(222, 107, 99, 0.4);
  padding: 6px 10px;
  background: rgba(80, 12, 12, 0.18);
}
.tiny {
  margin: 18px 0 0;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: #6f5c48;
}
.title-footer {
  position: absolute;
  bottom: calc(var(--safe-bottom) + 16px);
  left: 0;
  right: 0;
  text-align: center;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.24em;
  color: #5d4c3d;
}

/* ---------------- big buttons ---------------- */
.big-btn {
  appearance: none;
  position: relative;
  border: 3px solid #18100d;
  outline: 2px solid rgba(255, 243, 207, 0.55);
  outline-offset: 3px;
  background: var(--paper);
  color: #160e0b;
  font-family: var(--ui);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.045em;
  font-size: clamp(14px, 1.4vw, 18px);
  padding: 14px 27px;
  cursor: pointer;
  box-shadow: 5px 5px 0 rgba(0, 0, 0, 0.6);
  transition: transform 0.08s, background 0.1s;
}
.big-btn:hover { background: #fff8dd; transform: translate(-1px, -1px); box-shadow: 6px 6px 0 rgba(0,0,0,0.6); }
.big-btn:active { transform: translate(3px, 3px); box-shadow: 2px 2px 0 rgba(0,0,0,0.6); }
.big-btn.dark { background: #241714; color: #f0ddba; outline-color: rgba(255,243,207,0.25); }
.big-btn.dark:hover { background: #37231d; }
.big-btn.red { background: #a31717; color: #fff0e0; outline-color: #ff9c8a; }
.big-btn.red:hover { background: #c32121; }
.big-btn.green { background: var(--green); color: #07190b; outline-color: #b8ffb6; }
.big-btn.green:hover { background: #65d77b; }
.big-btn span.key { margin-left: 8px; background: #160e0b; color: #fff3cf; }

.link-btn {
  appearance: none;
  border: 0;
  background: transparent;
  color: #a08a70;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 10px 8px;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.link-btn:hover { color: #fff3cf; }
.link-btn .key { margin-left: 5px; }

/* ---------------- help ---------------- */
#help { background: rgba(4, 3, 3, 0.9); backdrop-filter: blur(5px); z-index: 55; }
.help-card {
  width: min(620px, 92vw);
  max-height: 88vh;
  overflow: auto;
  background: #17100e;
  border: 2px solid rgba(255,243,207,0.25);
  border-top: 6px solid var(--red);
  padding: clamp(18px, 3vw, 34px);
  box-shadow: 10px 10px 0 rgba(0,0,0,0.55);
}
.kicker {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.24em;
  color: #c89f70;
  text-transform: uppercase;
}
.help-card h2 {
  margin: 4px 0 14px;
  font-family: var(--ui);
  font-weight: 900;
  font-size: clamp(36px, 6vw, 64px);
  line-height: 0.83;
  letter-spacing: -0.05em;
  color: #f1dfb7;
  text-shadow: 3px 3px 0 #631010;
}
.help-card p { font-size: 13px; line-height: 1.55; color: #cbb796; }
.help-card p b { color: #fff3cf; }
.help-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 18px 0;
}
.help-grid > div {
  border: 1px solid rgba(255,243,207,0.16);
  padding: 10px 12px;
  background: rgba(255,243,207,0.03);
}
.help-grid b {
  display: block;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  color: #f5c88e;
  margin-bottom: 4px;
}
.help-grid span { font-family: var(--mono); font-size: 10px; line-height: 1.45; color: #a58f73; }
.help-warning {
  border: 1px dashed rgba(213,42,42,0.45);
  background: rgba(120, 15, 15, 0.12);
  padding: 10px 12px;
  color: #e6a49b !important;
  font-family: var(--mono);
  font-size: 11px !important;
}
.help-warning em { color: #ff6d5f; font-style: normal; font-weight: 700; }

/* ---------------- letter ---------------- */
.paper {
  position: relative;
  width: min(590px, 93vw);
  max-height: 88vh;
  overflow: auto;
  background:
    linear-gradient(105deg, rgba(255,255,255,0.15), transparent 40%),
    var(--paper);
  color: #211712;
  padding: clamp(20px, 3.4vw, 42px);
  transform: rotate(-1.1deg);
  box-shadow: 14px 16px 0 rgba(0,0,0,0.55), 0 0 70px rgba(255,220,150,0.1);
  border: 1px solid #a08a5d;
  font-family: var(--hand);
}
.paper::before {
  content: "";
  position: absolute;
  inset: 10px;
  border: 1px dashed rgba(80, 48, 20, 0.2);
  pointer-events: none;
}
.paper-top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: #6d5335;
  border-bottom: 1px solid rgba(70,40,15,0.25);
  padding-bottom: 8px;
}
.paper h2 {
  font-family: var(--ui);
  font-weight: 900;
  font-size: clamp(24px, 3.6vw, 36px);
  line-height: 1;
  margin: 20px 0 4px;
  letter-spacing: -0.02em;
}
.paper .hand { font-size: clamp(17px, 2.4vw, 24px); margin: 2px 0 16px; color: #8d1414; font-weight: 700; }
.paper .hand.small { font-size: clamp(14px, 1.9vw, 19px); color: #3f2c1a; margin: 14px 0; }
.paper .rules {
  margin: 0 0 18px;
  padding-left: 23px;
  font-size: clamp(13px, 1.6vw, 17px);
  line-height: 1.5;
}
.paper .rules li { margin-bottom: 9px; padding-left: 4px; }
.paper .rules b { background: rgba(213, 42, 42, 0.13); padding: 0 3px; color: #7c0d0d; }
.paper .signature { font-size: clamp(14px, 2vw, 20px); text-align: right; margin: 16px 0 4px; }
.paper .ps { font-size: clamp(10px, 1.3vw, 13px); color: #6d5335; font-family: var(--mono); line-height: 1.45; }
.paper-doodle {
  position: absolute;
  right: 28px;
  bottom: 74px;
  font-size: 44px;
  color: #a01414;
  transform: rotate(12deg);
  opacity: 0.75;
}
.paper .big-btn { display: block; margin: 20px auto 0; }

/* ---------------- peephole ---------------- */
.peephole {
  z-index: 44;
  background:
    radial-gradient(circle at 50% 45%, rgba(24, 14, 10, 0.55), #020101 72%),
    #020101;
  justify-content: center;
  gap: 12px;
}
.p-top {
  position: absolute;
  top: calc(var(--safe-top) + 20px);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: baseline;
  gap: 14px;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.2em;
  color: #d9c6a2;
  white-space: nowrap;
}
.p-top small { color: #876d51; font-size: 8px; letter-spacing: 0.24em; }
.p-lens {
  position: relative;
  width: min(64vmin, 580px);
  aspect-ratio: 1;
  border-radius: 50%;
  background: #060404;
  box-shadow:
    0 0 0 7px #1c1512,
    0 0 0 11px #0a0706,
    0 0 0 14px rgba(255, 243, 207, 0.13),
    0 0 60px 18px rgba(0,0,0,0.85),
    inset 0 0 70px rgba(0,0,0,0.9);
  overflow: hidden;
  flex: 0 0 auto;
}
#peepCanvas {
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
}
.p-glass {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 50%, transparent 38%, rgba(0,0,0,0.28) 62%, rgba(0,0,0,0.92) 100%),
    linear-gradient(130deg, rgba(255,255,255,0.07), transparent 38%);
  pointer-events: none;
  mix-blend-mode: multiply;
}
.p-glass::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background-image:
    radial-gradient(rgba(255,255,255,0.4) 0.5px, transparent 0.7px),
    radial-gradient(rgba(255,255,255,0.25) 0.5px, transparent 0.7px);
  background-size: 3px 3px, 5px 5px;
  opacity: 0.1;
  animation: grainShift 0.18s steps(2) infinite;
}
.p-glitch {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(180, 30, 30, 0.045) 3px 4px);
  animation: peepGlitch 6s steps(1) infinite;
}
@keyframes peepGlitch {
  0%, 88%, 100% { opacity: 1; transform: none; }
  89% { opacity: 0.55; transform: translateX(3px); }
  90% { opacity: 1; transform: translateX(-2px); }
  91% { opacity: 0.65; transform: none; }
}
.p-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  width: min(680px, 94vw);
  margin-top: 4px;
}
.p-hint {
  font-family: var(--mono);
  font-size: clamp(8px, 1vw, 10px);
  letter-spacing: 0.06em;
  color: #806d57;
  text-align: center;
  margin: 0;
  max-width: 80vw;
}
.peephole .link-btn { margin-top: -4px; }

/* ---------------- party banner ---------------- */
#partyBanner {
  position: absolute;
  left: 50%;
  top: 22%;
  z-index: 26;
  transform: translate(-50%, -50%) rotate(-2.5deg);
  text-align: center;
  pointer-events: none;
  animation: bannerIn 0.45s cubic-bezier(.2,1.7,.4,1);
}
#partyBanner span {
  display: block;
  font-family: var(--ui);
  font-weight: 900;
  font-size: clamp(42px, 8vw, 112px);
  line-height: 0.9;
  letter-spacing: -0.045em;
  color: #fff6c9;
  text-shadow:
    4px 4px 0 #cc1c1c,
    -3px -3px 0 #1954a8,
    0 0 40px rgba(255, 220, 80, 0.65);
  animation: partyWobble 1.1s steps(2) infinite;
}
#partyBanner small {
  display: block;
  margin-top: 14px;
  font-family: var(--mono);
  font-size: clamp(9px, 1.2vw, 13px);
  letter-spacing: 0.28em;
  color: #fff0bb;
  background: rgba(0,0,0,0.55);
  padding: 5px 12px;
}
@keyframes bannerIn {
  from { opacity: 0; transform: translate(-50%,-50%) scale(0.5) rotate(-9deg); }
  to { opacity: 1; transform: translate(-50%,-50%) scale(1) rotate(-2.5deg); }
}
@keyframes partyWobble {
  0%,100% { transform: rotate(-1.2deg) scale(1); }
  50% { transform: rotate(1.2deg) scale(1.015); }
}

#confetti { position: absolute; inset: 0; z-index: 25; pointer-events: none; overflow: hidden; }
.confetti-bit {
  position: absolute;
  top: -30px;
  width: 9px;
  height: 15px;
  opacity: 0.9;
  animation: confettiFall linear infinite;
}
@keyframes confettiFall {
  0% { transform: translate3d(0,-30px,0) rotate(0deg); }
  100% { transform: translate3d(var(--drift, 30px), 110vh, 0) rotate(var(--spin, 720deg)); }
}

/* ---------------- death ---------------- */
.death {
  z-index: 60;
  background: #000;
  overflow: hidden;
  padding: 0;
}
.death-static {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(rgba(255,255,255,0.7) 0.6px, transparent 0.9px),
    repeating-linear-gradient(0deg, rgba(255,255,255,0.1) 0 1px, transparent 1px 2px);
  background-size: 3px 3px, auto;
  opacity: 0.2;
  animation: staticJump 0.12s steps(2) infinite;
  mix-blend-mode: screen;
}
@keyframes staticJump {
  0% { transform: translate(0,0); }
  50% { transform: translate(-4px,2px); }
  100% { transform: translate(3px,-3px); }
}
.jumpface {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(90vmin, 900px);
  height: min(90vmin, 900px);
  transform: translate(-50%, -50%);
  object-fit: contain;
  filter: contrast(1.3) saturate(0.7) drop-shadow(0 0 30px #000);
  animation: faceShake 0.09s steps(2) infinite;
  pointer-events: none;
}
@keyframes faceShake {
  0% { transform: translate(-50%, -50%) scale(1.03) rotate(-0.7deg); }
  33% { transform: translate(calc(-50% + 9px), calc(-50% - 6px)) scale(1.055) rotate(0.8deg); }
  66% { transform: translate(calc(-50% - 7px), calc(-50% + 5px)) scale(1.02) rotate(-0.3deg); }
  100% { transform: translate(-50%, -50%) scale(1.045) rotate(0.5deg); }
}
.jumpwords {
  position: absolute;
  left: 50%;
  bottom: 7%;
  transform: translateX(-50%) rotate(-3deg);
  font-family: var(--ui);
  font-weight: 900;
  font-size: clamp(48px, 12vw, 170px);
  line-height: 0.8;
  letter-spacing: -0.04em;
  color: #d31717;
  text-shadow: 6px 6px 0 #000, -2px -2px 0 #fff3cf;
  animation: wordPulse 0.13s steps(2) infinite;
  pointer-events: none;
}
@keyframes wordPulse {
  0%,100% { transform: translateX(-50%) rotate(-3deg) scale(1); }
  50% { transform: translateX(-50%) rotate(-2deg) scale(1.04); }
}
.kill-card {
  position: relative;
  z-index: 3;
  width: min(620px, 92vw);
  background: #0b0707;
  border: 2px solid rgba(255, 80, 60, 0.4);
  border-top: 8px solid #a51212;
  padding: clamp(22px, 4vw, 44px);
  text-align: center;
  box-shadow: 12px 12px 0 rgba(0,0,0,0.65);
  animation: cardIn 0.4s ease-out;
}
@keyframes cardIn {
  from { opacity: 0; transform: translateY(16px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
