  margin: 6px 0 18px;
  font-family: var(--ui);
  font-weight: 900;
  font-size: clamp(52px, 9vw, 104px);
  line-height: 0.78;
  letter-spacing: -0.06em;
  color: #f1dfb7;
  text-shadow: 4px 4px 0 #8e0c0c, -2px -2px 0 #3a0303;
}
.kill-card p { color: #c6a78a; font-size: 13px; line-height: 1.6; }
.death .stats { justify-content: center; }

/* ---------------- win ---------------- */
#ending {
  z-index: 42;
  background: rgba(5, 3, 5, 0.55);
  backdrop-filter: blur(2px);
}
.end-card {
  width: min(660px, 93vw);
  background: rgba(12, 7, 10, 0.92);
  border: 3px solid rgba(255, 243, 207, 0.35);
  border-top: 8px solid #c2a31c;
  padding: clamp(22px, 4vw, 44px);
