  overflow: hidden;
}
.end-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: conic-gradient(from 0deg, rgba(255,60,60,0.09), rgba(255,220,60,0.09), rgba(60,255,120,0.09), rgba(60,140,255,0.09), rgba(255,60,60,0.09));
